/* A deliberately local, ephemeral design demo. Nothing calls the application. */
(() => {
  'use strict';
  const $ = (s, root = document) => root.querySelector(s);
  const frame = $('#frame'), overlay = $('#overlay');
  const TODAY = '2026-10-12', NOW = '11:20';
  const initial = JSON.parse(JSON.stringify(window.CALENDAR_DATA));
  let calendars, items, notes;
  const state = {view:'month', page:'calendar', date:TODAY, panel:true, lastCalendar:'personal', note:'trip-plan', dialog:null, start:'2026-09-01', end:'2026-11-30'};
  let undoAction = null, toastTimer, previousFocus = null, sequence = 100, todayAgenda = null;
  const paths = {
    calendar:'M4 5h12v12H4z M7 3v4 M13 3v4 M4 9h12 M7 12h.1 M10 12h.1 M13 12h.1 M7 15h.1 M10 15h.1',
    today:'M10 3v2 M10 15v2 M3 10h2 M15 10h2 M5 5l1.4 1.4 M13.6 13.6L15 15 M5 15l1.4-1.4 M13.6 6.4L15 5 M13 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
    eye:'M2 10s3-5 8-5 8 5 8 5-3 5-8 5-8-5-8-5 M12.5 10a2.5 2.5 0 1 1-5 0 2.5 2.5 0 0 1 5 0',
    plus:'M10 4v12 M4 10h12', left:'M12 4l-6 6 6 6', right:'M8 4l6 6-6 6', down:'M4 7l6 6 6-6', close:'M5 5l10 10 M15 5L5 15',
    page:'M5 3h7l4 4v10H5z M12 3v4h4 M8 10h5 M8 13h5', database:'M4 4h12v12H4z M4 8h12 M4 12h12 M8 4v12',
    search:'M13 8a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M12 12l5 5', home:'M3 9l7-6 7 6 M5 8v9h10V8 M8 17v-5h4v5',
    agent:'M5 6h10v10H5z M10 3v3 M3 9h2 M15 9h2 M7 10h.1 M13 10h.1 M8 13h4',
    clock:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0 M10 6v4l3 2', more:'M4 10h.1 M10 10h.1 M16 10h.1',
    sidebar:'M3 4h14v12H3z M8 4v12', star:'M10 2l2.4 5 5.5.8-4 3.9.9 5.5-4.8-2.6-4.8 2.6.9-5.5-4-3.9 5.5-.8z',
    settings:'M4 5h12 M4 10h12 M4 15h12 M7 3v4 M13 8v4 M8 13v4', trash:'M4 5h12 M7 5V3h6v2 M5 5l1 12h8l1-12 M8 8v6 M12 8v6',
    grip:'M7 5h.1 M13 5h.1 M7 10h.1 M13 10h.1 M7 15h.1 M13 15h.1', link:'M8 12l4-4 M7 13l-1 1a3 3 0 0 1-4-4l3-3a3 3 0 0 1 4 0 M13 7l1-1a3 3 0 0 1 4 4l-3 3a3 3 0 0 1-4 0',
    board:'M3 4h6v12H3z M12 4h5v7h-5z', check:'M4 10l4 4 8-8', undo:'M5 9H2V5 M2 9c3-7 13-6 15 1 1 4-3 7-6 7', keyboard:'M2 5h16v11H2z M5 8h.1 M8 8h.1 M11 8h.1 M14 8h.1 M5 11h.1 M8 11h.1 M11 11h.1 M14 11h.1 M6 14h8'
  };
  const icon = n => `<svg class="icon" viewBox="0 0 20 20" aria-hidden="true"><path d="${paths[n] || paths.page}"/></svg>`;
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const d = s => new Date(s + 'T12:00:00');
  const stamp = dt => `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;
  const add = (s, days) => {const x=d(s);x.setDate(x.getDate()+days);return stamp(x);};
  const monday = s => add(s,-((d(s).getDay()+6)%7));
  const fmt = (s, options) => d(s).toLocaleDateString('en-GB',options);
  const shortDate = s => fmt(s,{weekday:'short',day:'numeric',month:'short'});
  const monthTitle = s => fmt(s,{month:'long',year:'numeric'});
  const endTime = item => {const [h,m]=(item.time || '09:00').split(':').map(Number);const total=h*60+m+(Number(item.duration)||60);return `${String(Math.floor(total/60)%24).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;};
  const phone = () => frame.dataset.width === 'phone';
  const cal = id => calendars.find(c => c.id === id) || calendars[0];
  const colour = id => {const c=cal(id);return c?.color || `var(--${c?.palette || 'apricot'})`;};
  const cstyle = id => `--cal:${esc(colour(id))}`;
  const agent = () => `<span class="avatar" title="Assigned to Agent" aria-label="Assigned to Agent">${icon('agent')}</span>`;
  const itemList = (date, todayMode=false) => items.filter(i=>i.date===date && calendars.some(c=>c.id===i.calendar && (todayMode ? c.today && i.kind!=='mention' : c.visible))).sort((a,b)=>(a.time || '00:00').localeCompare(b.time || '00:00'));
  const ownedTask = i => i?.kind==='task';
  const taskOptions = selected => calendars.filter(c=>!c.database).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>● ${esc(c.name)}</option>`).join('');
  const button = (action, label, ico, cls='', extra='') => `<button type="button" class="${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
  function calendarPicker(selected, taskId=null){return `<div class="calendar-picker-wrap"><details class="calendar-picker"><summary style="${cstyle(selected)}"><span class="dot"></span><span>${esc(cal(selected)?.name)}</span>${icon('down')}</summary><div class="calendar-choices">${calendars.filter(c=>!c.database).map(c=>button('pick-calendar',`<span class="dot" style="${cstyle(c.id)}"></span>${esc(c.name)}`,'','',`data-calendar="${c.id}" ${taskId?`data-task="${taskId}"`:''} aria-pressed="${c.id===selected}"`)).join('')}</div></details>${taskId?'':`<input type="hidden" name="calendar" value="${selected}">`}</div>`;}
  const nav = (action,label,ico,selected=false) => button(action,label,ico,`nav-row ${selected?'selected':''}`);
  function reset(){({calendars,items,notes}=JSON.parse(JSON.stringify(initial)));sequence=100;todayAgenda?.destroy();todayAgenda=null;state.date=TODAY;state.view='month';state.page='calendar';state.panel=true;state.start='2026-09-01';state.end='2026-11-30';closeDialog(false);render();state.calendarMonth=TODAY.slice(0,7)+'-01';$('#screen').value='month';}
  function sidebar(){return `<aside class="sidebar"><div class="brand"><span class="calico-mark"></span>Notes</div>
    ${nav('pages','Search <span class="mono">Ctrl K</span>','search')}${nav('today-page','Today','today',state.page==='today')}${nav('calendar-page','Calendar','calendar',state.page==='calendar')}${nav('agent-task','Agent','agent')}
    <div class="nav-label">Favorites</div>${nav('cards','Weekly review','page',state.page==='cards')}${nav('note','Trip plan','page',state.page==='note')}
    <div class="nav-label">Pages</div>${nav('cards','Tasks board','board')}${nav('calendars','Projects','database')}${nav('calendars','Reading list','database')}
    <div class="nav-label">Recent notes</div>${notes.map(n=>`<button class="recent-note" draggable="true" data-note="${n.id}" data-action="open-note" data-id="${n.id}" title="Drag onto a day to add a date">${icon('page')}${esc(n.title)}${icon('grip')}</button>`).join('')}
    <div class="drag-caption">Drag a note onto a day to add a date reference.</div>
    <div class="sidebar-bottom">${button('create','New task','plus','primary')}${nav('shortcuts','Keyboard shortcuts','keyboard')}${nav('calendars','Calendar settings','settings')}</div></aside>`;}
  function calendarPanel(){return `<aside class="calendar-panel"><div class="panel-heading"><h3>Calendars</h3>${button('panel-close','','close','icon-btn','aria-label="Close calendars"')}</div>
    <div class="panel-cols"><span title="Show in calendar" aria-label="Show in calendar">${icon('eye')}</span><span title="Show in Today" aria-label="Show in Today">${icon('today')}</span></div>
    ${[false,true].map(db=>`<div class="calendar-group">${db?'From databases':'My calendars'}</div>${calendars.filter(c=>c.database===db).map(c=>`<div class="calendar-row" style="${cstyle(c.id)}"><span class="dot"></span><span class="calendar-name">${esc(c.name)}</span><button class="switch" role="switch" aria-checked="${c.visible}" data-action="toggle-calendar" data-id="${c.id}" title="Show ${esc(c.name)} in calendar" aria-label="Show ${esc(c.name)} in calendar"></button><button class="switch" role="switch" aria-checked="${c.today}" data-action="toggle-today" data-id="${c.id}" title="Show ${esc(c.name)} in Today" aria-label="Show ${esc(c.name)} in Today"></button>${button('calendar-menu','','more','row-menu',`data-id="${c.id}" aria-label="${esc(c.name)} calendar menu"`)}</div>`).join('')}`).join('')}
    ${button('new-calendar','New calendar','plus','new-calendar')}<div class="panel-note">${icon('eye')} Calendar visibility<br>${icon('today')} Include in Today<br><br>Agent is visible here and hidden from Today.</div></aside>`;}
  function header(){if(state.page==='today')return getTodayAgenda().toolbarHtml(state.date);if(state.page!=='calendar')return `<div class="document-top"><div>${button('calendar-page','Calendar','left','text-link')}</div><span class="muted small">${state.page==='note'?esc(notes.find(n=>n.id===state.note)?.title || 'Note'):'Tasks board'}</span><div class="header-actions">${button('calendars','','settings','icon-btn','aria-label="Calendars"')}${button('pages','','more','icon-btn','aria-label="More screens"')}</div></div>`;const title=monthTitle(state.date);return `<div class="page-top"><span>${icon(state.page==='calendar'?'calendar':'page')} ${state.page==='calendar'?'Calendar':'Notes'} · Personal vault</span><div>${button('note','Note with date chip','page')}${button('cards','Kanban & embed','board')}${button('shortcuts','?','','icon-btn','aria-label="Keyboard shortcuts"')}</div></div>
    <header class="calendar-header"><h1 class="header-title" id="month-title">${esc(title)}</h1>
    <div class="header-actions">${button('previous','','left','icon-btn','aria-label="Previous period"')}${button('go-today','Today','')}${button('next','','right','icon-btn','aria-label="Next period"')}
      <div class="view-switch" aria-label="Calendar view">${['month','week','day'].map(v=>button(`view-${v}`,v[0].toUpperCase()+v.slice(1),'',state.page==='calendar'&&state.view===v?'active':'',`aria-pressed="${state.page==='calendar'&&state.view===v}"`)).join('')}</div>
      ${button('jump','Jump to date','calendar','outline')}${button('calendars','','settings','icon-btn',`aria-label="Calendars" title="Calendars" aria-expanded="${state.panel}"`)}${button('create','New task','plus','primary')}
    </div><div class="phone-menu"><select id="phone-view" aria-label="Calendar view">${['month','week','day'].map(v=>`<option value="${v}" ${state.view===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select><div>${button('previous','','left','icon-btn','aria-label="Previous period"')}${button('go-today','Today','')}${button('next','','right','icon-btn','aria-label="Next period"')}</div>${button('calendars','','settings','icon-btn','aria-label="Calendars" title="Calendars"')}${button('pages','','more','icon-btn','aria-label="More screens"')}</div></header>`;}
  function dock(){return `<nav class="mobile-dock" aria-label="Bottom navigation">${button('pages','Pages','sidebar')}${button('today-page','Today','today',state.page==='today'?'active':'')}${button('calendar-page','Calendar','calendar',state.page==='calendar'?'active':'')}${button('pages','Search…','search','dock-search')}</nav>${button('create','','plus','fab','aria-label="New task"')}`;}
  function itemSource(i){if(i.kind==='db')return 'in '+(cal(i.calendar)?.name || 'Projects');if(i.kind==='todo'||i.kind==='mention')return 'in '+(notes.find(n=>n.id===i.noteId)?.title || 'a note');return cal(i.calendar)?.name || 'Personal';}
  function kindIcon(i,checkbox=true){if(i.kind==='db')return icon('database');if(i.kind==='mention')return icon('page');return `${checkbox?`<input type="checkbox" data-check="${i.id}" ${i.done?'checked':''} aria-label="Complete ${esc(i.title)}">`:icon(i.time?'clock':'check')}${i.kind==='todo'?icon('page'):''}`;}
  function chip(i){return `<div class="item-chip ${i.kind==='mention'?'mention':''} ${i.done?'done':''}" role="button" tabindex="0" draggable="${ownedTask(i)}" data-item="${i.id}" data-kind="${i.kind}" style="${cstyle(i.calendar)}" title="${esc(cal(i.calendar)?.name+' · '+itemSource(i)+' · '+(i.time?i.time+' · ':'')+i.title)}">${kindIcon(i)}${i.time?`<time>${i.time}</time>`:''}<span class="item-title">${esc(i.title)}</span>${i.assignee==='agent'?agent():''}</div>`;}
  function itemCard(i,{compact=false,overdue=false}={}){
    if(!i)return '';
    const name=cal(i.calendar)?.name || 'Personal',fromNote=i.kind==='todo'||i.kind==='mention';
    const source=fromNote?(notes.find(n=>n.id===i.noteId)?.title || 'a note'):name;
    const provenance=`Calendar: ${name}${fromNote?' · Note: '+source:i.kind==='db'?' · Database: '+source:''}`;
    const sourceIcon=fromNote?icon('page'):i.kind==='db'?icon('database'):'<span class="dot"></span>';
    const date=overdue?`<span class="item-date overdue-date">${shortDate(i.date)}</span>`:compact?`<span class="item-date">${shortDate(i.date)}</span>`:'';
    const time=i.time&&!overdue?`<time class="item-time">${esc(i.time)}</time>`:'';
    const assignee=i.assignee==='agent'?`<span class="item-agent" title="Assigned to Agent" aria-label="Assigned to Agent">${icon('agent')}<span>Agent</span></span>`:'';
    const meta=date+time+assignee;
    const kind=i.kind==='db'?'Dated database row':i.kind==='todo'?'Dated to-do in a note':i.kind==='mention'?'Date mention':i.time?'Timed task':'Task';
    const left=fromNote&&i.kind==='todo'?`<input type="checkbox" data-check="${i.id}" ${i.done?'checked':''} aria-label="Complete ${esc(i.title)}">`:kindIcon(i);
    return `<div class="item-card agenda-row ${compact?'compact-card':''} ${overdue?'overdue-card':''} ${i.done?'done':''} ${i.kind==='mention'?'reference-card':''}" role="button" tabindex="0" draggable="${ownedTask(i)}" data-item="${i.id}" data-kind="${i.kind}" data-calendar-id="${i.calendar}" style="${cstyle(i.calendar)}"><div class="item-kind" title="${kind}">${left}</div><div class="item-card-body ${meta?'has-meta':'no-meta'}"><div class="item-title agenda-title" title="${esc(i.title)}">${esc(i.title)}</div>${meta?`<div class="item-card-meta">${meta}</div>`:''}<button type="button" class="item-source item-calendar-marker" data-action="item-calendar" data-id="${i.id}" aria-label="${esc(provenance)}" aria-expanded="false"><span class="meta-separator" aria-hidden="true">·</span>${sourceIcon}<span class="item-source-label">${esc(source)}</span><span class="item-calendar-tooltip" role="tooltip">${esc(provenance)}</span></button></div></div>`;
  }
  function agendaRow(i,snippet=false){return itemCard(i,{snippet});}
  function agenda(date, todayMode=false){const list=itemList(date,todayMode);return `<section class="agenda"><div class="agenda-heading"><h3>${shortDate(date)}</h3>${button('create','New task','plus','text-link',`data-date="${date}"`)}</div>${list.length?list.map(i=>agendaRow(i)).join(''):'<p class="empty">Nothing planned. Add a task, or give a note a date with @.</p>'}</section>`;}
  function month(){const groups=[];let cursor=monday(state.start);const end=monday(state.end);let group=null;
    while(cursor<=end){const key=add(cursor,3).slice(0,7);if(!group||group.key!==key){group={key,weeks:[]};groups.push(group);}group.weeks.push(cursor);cursor=add(cursor,7);}
    return `<div class="weekday-row">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(n=>`<span>${n}</span>`).join('')}</div><div class="month-scroll" id="month-scroll">${groups.map(g=>`<section class="month-section" data-month="${g.key}"><div class="month-label">${monthTitle(g.key+'-01')}</div>${g.weeks.map(w=>`<div class="week-row">${Array.from({length:7},(_,col)=>{const date=add(w,col),list=itemList(date),first=d(date).getDate()===1;return `<div class="day-cell ${col>4?'weekend':''} ${date.slice(0,7)!==g.key?'outside':''} ${date===state.date?'selected':''}" data-day="${date}" tabindex="0" role="button" aria-label="${shortDate(date)}, ${list.length} items"><span class="day-number ${first?'first-day':''} ${date===TODAY?'today':''}">${first?`${d(date).getDate()} ${fmt(date,{month:'short'})}`:d(date).getDate()}</span>${button('cell-create','','plus','cell-add',`data-date="${date}" aria-label="New task on ${shortDate(date)}"`)}${list.slice(0,3).map(chip).join('')}${list.length>3?button('overflow',`+${list.length-3} more`,'','more-items',`data-date="${date}"`):''}<div class="mobile-dots">${list.slice(0,4).map(i=>`<span class="dot" style="${cstyle(i.calendar)}"></span>`).join('')}${list.length>4?'<span class="small quiet">+</span>':''}</div></div>`;}).join('')}</div>`).join('')}</section>`).join('')}</div>${phone()?agenda(state.date):''}`;
  }
  function weekStrip(selected=state.date,todayMode=false){const start=monday(selected);return `<div class="week-strip swipe-surface" data-swipe="week">${Array.from({length:7},(_,idx)=>{const date=add(start,idx);return button('select-day',`<span>${fmt(date,{weekday:'short'})}</span><strong>${d(date).getDate()}</strong><span class="strip-dots">${itemList(date,todayMode).slice(0,3).map(i=>`<span class="dot" style="${cstyle(i.calendar)}"></span>`).join('')}</span>`,'',`week-tile ${date===selected?'selected':''} ${date===TODAY?'today':''}`,`data-date="${date}" aria-label="${shortDate(date)}" aria-pressed="${date===selected}"`);}).join('')}</div>`;}
  function timeGrid(single=false){const days=single?[state.date]:Array.from({length:7},(_,i)=>add(monday(state.date),i));return `<div class="${single?'single-day':'calendar-content'}"><div class="grid-header"><span></span>${days.map(date=>`<div class="grid-day ${date===TODAY?'is-today':''}">${fmt(date,{weekday:'short'})}<strong>${d(date).getDate()}</strong></div>`).join('')}</div>${single?'':`<div class="all-day"><div class="all-day-label">All day</div>${days.map(date=>`<div class="all-day-cell" data-day="${date}">${itemList(date).filter(i=>!i.time).map(chip).join('')}</div>`).join('')}</div>`}<div class="time-scroll"><div class="time-grid"><div class="hours">${Array.from({length:24},(_,i)=>`<div class="hour-label">${String(i).padStart(2,'0')}:00</div>`).join('')}${days.includes(TODAY)?`<span class="now-gutter-label" style="top:680px">now ${NOW}</span>`:''}</div>${days.map(date=>{
      const timed=itemList(date).filter(i=>i.time);const placements=new Map();let active=[];
      for(const i of timed){const [h,m]=i.time.split(':').map(Number),start=h*60+m;active=active.filter(a=>a.end>start);const lane=[0,1,2,3].find(n=>!active.some(a=>a.lane===n)) ?? 0;const placement={lane,start,end:start+(Number(i.duration)||60),group:[]};active.push(placement);placement.group=[...active];for(const a of active)a.group=[...new Set([...a.group,...active])];placements.set(i.id,placement);}
      return `<div class="time-column ${d(date).getDay()===0||d(date).getDay()===6?'weekend':''}" data-slot-day="${date}">${Array.from({length:24},(_,h)=>button('slot-create','','','hour-slot',`data-date="${date}" data-time="${String(h).padStart(2,'0')}:00" aria-label="New task ${shortDate(date)} at ${h}:00"`)).join('')}${timed.map(i=>{const p=placements.get(i.id),count=Math.max(...p.group.map(a=>a.lane))+1,top=p.start,height=Math.max(22,Math.min(p.end,1440)-p.start);return `<div class="time-block ${height<38?'short-block':''} ${i.done?'done':''}" role="button" tabindex="0" draggable="${ownedTask(i)}" data-item="${i.id}" style="${cstyle(i.calendar)};top:${top}px;height:${height}px;left:calc(${p.lane/count*100}% + 3px);width:calc(${100/count}% - 6px)" title="${esc(cal(i.calendar)?.name+' · '+itemSource(i)+' · '+i.title)}, ${i.time}–${endTime(i)}">${i.assignee==='agent'?agent():''}<time>${icon('clock')}${i.time}${height>38?' – '+endTime(i):''}</time><span class="item-title">${esc(i.title)}</span></div>`;}).join('')}${date===TODAY?`<div class="now-line" style="top:680px"></div>`:''}</div>`;}).join('')}</div></div></div>`;}
  function day(){const list=itemList(state.date);return `<div class="day-layout">${timeGrid(true)}<aside class="due-panel"><h3>Due this day</h3>${list.filter(i=>!i.time&&i.kind!=='mention').map(i=>agendaRow(i)).join('') || '<p class="empty">No untimed tasks.</p>'}<h3 style="margin-top:28px">Mentioned in</h3>${list.filter(i=>i.kind==='mention').map(i=>agendaRow(i,true)).join('')||'<p class="empty">No date mentions on this day.</p>'}${button('note','View a date mention','page','text-link')}</aside></div>`;}
  function calendarContent(){if(state.view==='month')return month();if(phone())return `${state.view==='week'?weekStrip():`<div class="agenda-heading" style="padding:16px 18px 0"><h3>${shortDate(state.date)}</h3>${button('jump','Jump to date','calendar','text-link')}</div>`}<div class="calendar-content swipe-surface" data-swipe="${state.view}"><div class="swipe-hint">Drag or swipe to the ${state.view==='week'?'next week':'next day'}</div>${agenda(state.date)}</div>`;return state.view==='week'?timeGrid():day();}
  function compact(i){return itemCard(i,{compact:true});}
  function cards(){const task=items.find(i=>i.id==='i12'), samples=['i12','i16','i15','i14'].map(id=>items.find(i=>i.id===id)).filter(Boolean);const groups=[{name:'To do',list:samples.filter(i=>!i.done&&i.id!=='i15')},{name:'In progress',list:samples.filter(i=>!i.done&&i.id==='i15')},{name:'Done',list:samples.filter(i=>i.done)}];return `<article class="content-page"><h1>Task card in kanban & embed</h1><p class="muted">One dated task, wherever you keep it.</p><div class="kanban">${groups.map(g=>`<section class="kanban-column"><div class="column-title">${g.name}<span>${g.list.length}</span></div>${g.list.map(compact).join('')||'<p class="empty">No tasks here.</p>'}</section>`).join('')}</div><div class="note-prose"><h2>Weekly review</h2><p>Keep the calendar quiet this week. A few things to finish before the trip:</p><div class="embed">${compact(task)}</div><p class="small muted">Embedded task · changes here appear in the calendar too.</p>${button('calendar-page','Open calendar','calendar','text-link')}</div></article>`;}
  function notePage(){const note=notes.find(n=>n.id===state.note)||notes[0],refs=items.filter(i=>i.noteId===note.id);return `<article class="content-page"><div class="quiet small">${icon('page')} Personal / Notes</div><h1>${esc(note.title)}</h1><div class="note-meta"><span class="badge">Note</span>${refs.map(i=>button('date-link',`${icon('calendar')}${shortDate(i.date)}`,'','date-chip',`data-date="${i.date}"`)).join('')}${button('note-date','Add date','plus','text-link')}</div><div class="note-prose">${note.body.split('\n\n').map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('')}<h2>${note.id==='trip-plan'?'Before we leave':'Follow-up'}</h2><p>${note.id==='trip-plan'?'Check the train times and keep Friday free for planning.':'Keep the next conversation grounded in the open questions.'} ${button('date-link','@'+shortDate(refs[0]?.date || '2026-10-16'),'','mention-inline',`data-date="${refs[0]?.date || '2026-10-16'}"`)}</p><p class="muted small">A date mention links this note to the calendar. The note stays here.</p>${button('calendar-page','Open calendar','calendar','text-link')}${button('cards','See task embed','board','text-link')}</div></article>`;}
  function getTodayAgenda(){if(!todayAgenda)todayAgenda=window.createTodayAgenda({today:TODAY,add,monday,shortDate,itemList:date=>itemList(date,true),itemCard,overdue:()=>items.filter(i=>i.date<TODAY&&!i.done&&i.kind!=='mention'&&cal(i.calendar)?.today),weekStrip:date=>weekStrip(date,true),onDateChange:date=>{state.date=date;},button,icon,esc});return todayAgenda;}
  function todayPage(){return getTodayAgenda().html(state.date);}
  function scrollToday(date,smooth=true){if(!validDate(date))return;closeDialog(false);if(state.page!=='today'){state.date=date;state.page='today';render(false);}getTodayAgenda().scrollTo(date,smooth);}
  function render(keepScroll=true){const old=$('#month-scroll')?.scrollTop,oldScroller=$('#today-scroll'),oldToday=oldScroller?.scrollTop,oldDay=oldScroller?.querySelector(`.today-day[data-date="${state.date}"]`),todayOffset=oldDay?oldToday-oldDay.offsetTop:0;todayAgenda?.destroy();$('#app').innerHTML=`${sidebar()}<main class="workspace"><div class="breadcrumb">${icon('home')} Personal vault ${icon('right')} ${state.page==='today'?'Today':state.page==='calendar'?'Calendar':state.page==='note'?'Notes':'Tasks board'} <span class="spacer"></span>${button('shortcuts','','keyboard','icon-btn','aria-label="Keyboard shortcuts"')}</div><div class="sheet">${header()}${state.page==='calendar'?`<div class="calendar-main"><div class="calendar-content">${calendarContent()}</div>${state.panel&&!phone()?calendarPanel():''}</div>`:state.page==='cards'?cards():state.page==='note'?notePage():todayPage()}</div></main>${dock()}`;
    if(state.page==='calendar'&&state.view==='month'){const scroll=$('#month-scroll');if(keepScroll&&old!=null)scroll.scrollTop=old;else scrollToDate(state.date);scroll.addEventListener('scroll',onMonthScroll,{passive:true});}
    for(const scroller of frame.querySelectorAll('.time-scroll'))scroller.scrollTop=420;
    if(state.page==='today'){getTodayAgenda().mount(frame,state.date,null);if(keepScroll&&oldToday!=null){const scroller=$('#today-scroll'),section=scroller.querySelector(`.today-day[data-date="${state.date}"]`);if(section)scroller.scrollTop=section.offsetTop+Math.max(-64,Math.min(todayOffset,section.offsetHeight-40));}}
    bindSwipe();
  }
  function ensureRange(date){if(date<state.start)state.start=date.slice(0,7)+'-01';if(date>state.end){const x=d(date);x.setMonth(x.getMonth()+1,0);state.end=stamp(x);}}
  function scrollToDate(date){const scroll=$('#month-scroll');const cell=$(`[data-day="${date}"]`,scroll || document);if(scroll&&cell){const section=cell.closest('.month-section');scroll.scrollTop=Math.max(0,section.offsetTop-scroll.offsetTop);}}
  function onMonthScroll(){const scroll=$('#month-scroll');const top=scroll.getBoundingClientRect().top;let current=null;for(const section of scroll.querySelectorAll('.month-section')){if(section.getBoundingClientRect().top<=top+32)current=section;}
    if(current){$('#month-title').textContent=monthTitle(current.dataset.month+'-01');state.calendarMonth=current.dataset.month+'-01';}
  }
  function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(d(s).getTime())&&stamp(d(s))===s;}
  function goDate(date,view=state.view){if(!validDate(date))return;closeDialog(false);ensureRange(date);state.date=date;state.calendarMonth=date.slice(0,7)+'-01';state.page='calendar';state.view=view;$('#screen').value=view;render(false);}
  function move(amount){if(state.page==='today'){scrollToday(add(state.date,amount));return;}let date;if(state.view==='month'){const x=d(state.calendarMonth||state.date);x.setDate(1);x.setMonth(x.getMonth()+amount);date=stamp(x);}else date=add(state.date,amount*(state.view==='week'?7:1));goDate(date);}
  function bindSwipe(){for(const surface of frame.querySelectorAll('[data-swipe]')){let start=null;surface.addEventListener('pointerdown',e=>{if(e.target.closest('input,select,textarea'))return;start={x:e.clientX,y:e.clientY,id:e.pointerId};});surface.addEventListener('pointerup',e=>{if(!start||e.pointerId!==start.id)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5){surface.addEventListener('click',ev=>ev.stopImmediatePropagation(),{capture:true,once:true});move(dx<0?1:-1);}});surface.addEventListener('pointercancel',()=>start=null);}}
  function showDialog(type,body,anchor=null,sheet=false){previousFocus=document.activeElement;state.dialog=type;const rect=frame.getBoundingClientRect(),ar=anchor?.getBoundingClientRect();let x=ar?ar.left-rect.left:rect.width/2-170,y=ar?ar.bottom-rect.top+5:100;x=Math.max(12,Math.min(x,rect.width-352));y=Math.max(12,Math.min(y,rect.height-(type==='composer'?490:460)));overlay.innerHTML=`<div class="overlay-backdrop" data-action="close"></div><section class="dialog ${sheet?'side-sheet':'popover'}" role="dialog" aria-modal="true" aria-label="${type==='composer'?'Create task':type==='task'?'Task card':type}" tabindex="-1" ${sheet?'':`style="left:${x}px;top:${y}px"`}>${body}</section>`;setTimeout(()=>{const focus=$('[autofocus]',overlay)||$('.dialog',overlay);focus?.focus();},0);}
  function closeDialog(restore=true){const refresh=state.sheetDirty;state.sheetDirty=false;overlay.innerHTML='';state.dialog=null;if(refresh)render();if(restore&&previousFocus?.isConnected)previousFocus.focus();}
  const dialogHeader = title => `<div class="dialog-header"><h3>${title}</h3>${button('close','','close','icon-btn','aria-label="Close sheet"')}</div>`;
  function openTask(id){const i=items.find(x=>x.id===id);if(!i)return;if(i.kind==='mention'){state.note=i.noteId;state.page='note';closeDialog(false);render();$('#screen').value='note';return;}const db=i.kind==='db',todo=i.kind==='todo';showDialog('task',`${dialogHeader(db?'Database row':todo?'Dated to-do':'Task')}<textarea class="task-title" rows="${Math.max(1,Math.ceil(i.title.length/(phone()?25:29)))}" data-edit="title" data-id="${i.id}" aria-label="Task title">${esc(i.title)}</textarea><label class="task-status"><input type="checkbox" data-check="${i.id}" ${i.done?'checked':''}>${i.done?'Done':'To do'}</label>${db||todo?`<p class="muted small">${db?'From '+esc(cal(i.calendar)?.name)+' · Due date property':'To-do in '+esc(notes.find(n=>n.id===i.noteId)?.title || 'a note')}</p>`:''}
      <div class="property"><label>${icon('calendar')} Date</label><input type="date" data-edit="date" data-id="${i.id}" value="${i.date}" aria-label="Task date"></div>
      <div class="property"><label>${icon('clock')} Time</label>${i.time?`<div style="display:flex;gap:5px"><input type="time" data-edit="time" data-id="${i.id}" value="${i.time}" aria-label="Task time">${button('remove-time','','close','icon-btn',`data-id="${i.id}" aria-label="Remove time"`)}</div>`:button('add-time','Add time','plus','text-link',`data-id="${i.id}"`)}</div>
      <div class="property" ${i.time?'':'hidden'}><label>${icon('clock')} Duration</label><select data-edit="duration" data-id="${i.id}" aria-label="Task duration" ${!i.time?'disabled':''}>${[15,30,45,60,90,120,180].map(n=>`<option value="${n}" ${(i.duration||60)===n?'selected':''}>${n<60?n+' min':n/60+' h'}</option>`).join('')}</select></div>
      <div class="property"><label>${icon('agent')} Assignee</label><div style="display:flex;gap:8px;align-items:center">${i.assignee==='agent'?agent():'<span class="avatar">Me</span>'}<select data-edit="assignee" data-id="${i.id}" aria-label="Assignee"><option value="me" ${i.assignee!=='agent'?'selected':''}>Me</option><option value="agent" ${i.assignee==='agent'?'selected':''}>Agent</option></select></div></div>
      ${i.assignee==='agent'?'<div class="hint">Scheduled runs come later.</div>':''}<div class="property"><label>Calendar</label>${db?`<span class="badge"><span class="dot" style="${cstyle(i.calendar)}"></span>${esc(cal(i.calendar)?.name)}</span>`:calendarPicker(i.calendar,i.id)}</div>
      <div class="body-label">Notes</div><textarea data-edit="body" data-id="${i.id}" aria-label="Task body">${esc(i.body)}</textarea><div class="backlinks"><div class="body-label" style="margin-top:0">Backlinks / Mentioned in</div>${button('cards','Weekly review · embedded task','link')}${button('open-note',todo?'Apartment repairs':'Trip plan','page','',`data-id="${i.noteId || 'trip-plan'}"`)}${button('show-task-day','Show in calendar','calendar','text-link',`data-date="${i.date}" data-id="${i.id}"`)}</div>`,null,true);$('#screen').value='task';requestAnimationFrame(()=>resizeTitle($('.task-title',overlay)));}
  function composer(date=state.date,time=null,anchor=null,draft=null){showDialog('composer',`${dialogHeader('New task')}<form id="composer"><input class="composer-title" name="title" placeholder="What needs doing?" aria-label="Task title" value="${esc(draft?.title || '')}" autofocus required><div class="composer-fields"><label>Date<input name="date" type="date" value="${date}" required></label><label><input name="timed" type="checkbox" ${time?'checked':''}>Add time</label><div class="time-fields" ${time?'':'hidden'}><label>Time<input name="time" type="time" value="${time||'09:00'}"></label><label>Duration<select name="duration"><option value="30">30 min</option><option value="60" selected>1 h</option><option value="90">1.5 h</option><option value="120">2 h</option></select></label></div><label>Calendar${calendarPicker(draft?.calendar||state.lastCalendar)}</label><div id="composer-calendar-hint" class="small quiet" ${state.page==='today'&&!cal(draft?.calendar||state.lastCalendar)?.today?'':'hidden'}>This calendar is hidden from Today. Your task will appear in Calendar.</div><label>Assignee<select name="assignee"><option value="me">Me</option><option value="agent" ${draft?.assignee==='agent'?'selected':''}>Agent</option></select></label><div class="small quiet" id="agent-hint" ${draft?.assignee==='agent'?'':'hidden'}>${agent()} Scheduled runs come later.</div></div><div class="error" id="composer-error" aria-live="polite"></div><div class="composer-actions">${button('open-full','Open full','','text-link')}<button type="submit" class="primary">${icon('plus')}Create task</button></div><div class="quiet small" style="margin-top:10px">${phone()?'Saved to the selected calendar.':'Enter to create · Esc to close'}</div></form>`,anchor);$('#screen').value='create';}
  function createFromForm(full=false){const form=$('#composer');if(!form)return;const f=new FormData(form),title=String(f.get('title')).trim(),date=String(f.get('date'));if(!title||!validDate(date)){if(full&&!title)form.elements.title.value='Untitled task';else{$('#composer-error').textContent=!title?'Give the task a title.':'Choose a valid date.';form.elements.title.focus();return;}}
    const time=f.get('timed')?String(f.get('time')):null;if(time&&!/^\d{2}:\d{2}$/.test(time)){$('#composer-error').textContent='Choose a time.';return;}const task={id:'new-'+(++sequence),title:title||'Untitled task',date,calendar:String(f.get('calendar')),assignee:String(f.get('assignee')),kind:'task',done:false,time,duration:time?Number(f.get('duration')):null,body:'',snippet:'',noteId:null};items.push(task);state.lastCalendar=task.calendar;ensureRange(date);const inToday=state.page==='today';state.date=date;if(!inToday)state.page='calendar';cal(task.calendar).visible=true;closeDialog(false);render(false);toast(`Created '${task.title}'${inToday&&!cal(task.calendar)?.today?' · calendar hidden from Today':''}`,()=>{items=items.filter(i=>i.id!==task.id);render();});if(full)openTask(task.id);}
  function overflowDay(date=TODAY,anchor=null){showDialog('overflow',`${dialogHeader(shortDate(date))}${itemList(date).map(i=>agendaRow(i)).join('')||'<p class="empty">Nothing planned.</p>'}${button('cell-create','Add task','plus','text-link',`data-date="${date}"`)}${button('show-task-day','Open day view','calendar','text-link',`data-date="${date}"`)}`,anchor);$('#screen').value='overflow';}
  function jump(anchor=null,pickerDate=state.date){const start=monday(pickerDate.slice(0,7)+'-01');showDialog('jump',`${dialogHeader('Jump to date')}<div class="jump-month-head">${button('jump-prev','','left','icon-btn',`data-date="${pickerDate}" aria-label="Previous month"`)}<strong>${monthTitle(pickerDate)}</strong>${button('jump-next','','right','icon-btn',`data-date="${pickerDate}" aria-label="Next month"`)}</div><div class="mini-calendar">${['M','T','W','T','F','S','S'].map(n=>`<span>${n}</span>`).join('')}${Array.from({length:42},(_,idx)=>{const date=add(start,idx);return button('jump-select',d(date).getDate(),'',`${date===state.date?'selected':''} ${date.slice(0,7)!==pickerDate.slice(0,7)?'quiet':''}`,`data-date="${date}" aria-label="${shortDate(date)}"`);}).join('')}</div><form id="jump-form"><input class="jump-date" type="date" name="date" value="${state.date}" aria-label="Jump date" required><button type="submit" class="primary" style="width:100%">Go to date</button></form>`,anchor);$('#screen').value='jump';}
  function shortcuts(anchor=null){showDialog('shortcuts',`${dialogHeader('Keyboard shortcuts')}<div class="shortcut-list">${[['T','Back to today'],['M / W / D','Month / Week / Day'],['← / →','Previous / next period'],['J / K','Next / previous period'],['↑ / ↓','Previous / next day'],['G','Jump to date'],['N','New task'],['Esc','Close sheet or popover'],['?','Show shortcuts']].map(([k,v])=>`<kbd>${k}</kbd><span>${v}</span>`).join('')}</div><p class="quiet small" style="margin-top:22px">Desktop shortcuts pause while you type in a field.</p>`,anchor);$('#screen').value='shortcuts';}
  function calendarEditor(id=null,anchor=null){const c=id?cal(id):null;showDialog('calendar-editor',`${dialogHeader(c?'Edit calendar':'New calendar')}<form class="calendar-editor" id="calendar-form" data-id="${c?.id||''}"><label for="calendar-name">Name</label><input id="calendar-name" name="name" value="${esc(c?.name||'')}" placeholder="Calendar name" autofocus required><label>Colour</label><div class="color-choices">${['apricot','paw','moss','duvet','sun','sky'].map(p=>button('choose-color','','','color-choice',`style="--cal:var(--${p})" data-color="${p}" title="${p}" aria-label="${p}" aria-pressed="${p===(c?.palette||'apricot')}"`)).join('')}</div><input type="hidden" name="palette" value="${c?.palette||'apricot'}"><div class="composer-actions">${c?button('delete-calendar','Delete calendar','trash','delete-action',`data-id="${c.id}"`):'<span></span>'}<button type="submit" class="primary">${c?'Save changes':'Create calendar'}</button></div><p class="quiet small" style="margin-top:18px">${c?.database?'Mockup only: the database remains in the vault.':'Deleting a calendar keeps its tasks in Personal.'}</p></form>`,anchor);}
  function pages(){showDialog('pages',`${dialogHeader('Your vault')}<div class="menu-list">${button('calendar-page','Calendar','calendar')}${button('today-page','Today','today')}${button('today-example-future','Today · next week','right')}${button('today-example-past','Today · last week','left')}${button('today-example-sync','Week strip sync','calendar')}${button('today-example-create','Create on a future day','plus')}${button('today-example-created','Future task created','check')}${button('source-example','Item calendar & source','link')}${button('how-fits','How it fits','page')}${button('note','Note with date chip','page')}${button('cards','Task card in kanban & embed','board')}${button('jump','Jump to date','calendar')}${button('overflow','Busy day / overflow','more')}${button('agent-task','Agent-assigned task','agent')}${button('shortcuts','Keyboard shortcuts','keyboard')}</div><div class="body-label">Recent notes · drag onto a day on desktop</div>${notes.map(n=>button('open-note',esc(n.title),'page','',`data-id="${n.id}" draggable="true" data-note="${n.id}"`)).join('')}`);}
  function toast(message,undo=null){clearTimeout(toastTimer);undoAction=undo;$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?button('undo','Undo','undo'):''}`;$('#toast').classList.add('show');toastTimer=setTimeout(()=>{$('#toast').classList.remove('show');undoAction=null;},6500);}
  function showLegend(){showDialog('how-it-fits',`${dialogHeader('How it fits')}<p>Calendars group dated items. The colour tells you the calendar; the source label tells you where it lives.</p><p class="muted">Today includes tasks, dated database rows and to-dos from calendars with <strong>Show in Today</strong> enabled. Plain @date references appear only in Calendar.</p><div class="kind-legend"><span><span class="legend-checkbox"></span> Task</span><span><span class="legend-checkbox"></span>${icon('clock')} Timed task</span><span>${icon('database')} Dated database row</span><span><span class="legend-checkbox"></span>${icon('page')} To-do in a note</span><span>${icon('page')} @date reference · Calendar only</span></div>`);$('#screen').value='legend';}
  function closeItemSources(except=null){frame.querySelectorAll('.show-source').forEach(card=>{if(card===except)return;card.classList.remove('show-source');$('.item-calendar-marker',card)?.setAttribute('aria-expanded','false');});}
  function showItemCalendar(id,target,force=false){const card=target?.closest('.item-card');if(!card)return;const open=force||!card.classList.contains('show-source');closeItemSources(card);card.classList.toggle('show-source',open);target.setAttribute('aria-expanded',String(open));}
  document.addEventListener('click',e=>{if(!e.target.closest('.item-calendar-marker'))closeItemSources();});
  function showSourceExample(){const i=items.find(i=>i.kind==='todo'&&i.noteId==='trip-plan'&&i.date>=TODAY)||items.find(i=>i.id==='i19');state.page='today';state.date=i.date;render(false);const marker=$(`.today-day[data-date="${i.date}"] .item-card[data-item="${i.id}"] .item-calendar-marker`);showItemCalendar(i.id,marker,true);$('#screen').value='source';}
  function showTodayScreen(screen){closeDialog(false);state.page='today';state.date=screen==='today-past'?'2026-10-07':screen==='today-future'?'2026-10-23':screen==='today-sync'?'2026-10-20':screen==='today-create'||screen==='today-created'?'2026-10-22':TODAY;if(screen==='today-created'&&!items.some(i=>i.id==='demo-future-task'))items.push({id:'demo-future-task',title:'Pack the charger',date:'2026-10-22',calendar:'personal',kind:'task',done:false,assignee:'me',time:null,duration:null,body:'Added from Thursday’s agenda. The same task appears in Calendar.',noteId:null});state.lastCalendar='personal';render(false);$('#screen').value=screen;if(screen==='today-create'){const anchor=$('.today-day[data-date="2026-10-22"] [data-action="create"]');composer('2026-10-22',null,anchor);$('#screen').value=screen;}if(screen==='today-sync')toast('Tap a day, or scroll: the week strip follows your place.');}
  function setPage(page){closeDialog(false);state.page=page;$('#screen').value=page==='calendar'?state.view:page;render(false);}
  function handleAction(action,target){const date=target?.dataset.date || state.date,id=target?.dataset.id;
    if(action.startsWith('view-')){goDate(state.date,action.slice(5));return;}
    switch(action){
      case 'close':closeDialog();break;
      case 'calendar-page':if(state.page==='today'&&state.view==='month')state.view='week';setPage('calendar');break;
      case 'today-page':setPage('today');break;
      case 'go-today':if(state.page==='today')scrollToday(TODAY);else goDate(TODAY);break;
      case 'back-to-today':scrollToday(TODAY);break;
      case 'today-week-prev':scrollToday(add(monday(state.date),-7));break;
      case 'today-week-next':scrollToday(add(monday(state.date),7));break;
      case 'previous':move(-1);break;case 'next':move(1);break;
      case 'create':case 'cell-create':composer(date,null,target);break;
      case 'slot-create':composer(date,target.dataset.time,target);break;
      case 'open-full':createFromForm(true);break;
      case 'overflow':overflowDay(target?.dataset.date || TODAY,target);break;
      case 'jump':jump(target);break;
      case 'jump-prev':case 'jump-next':{const x=d(date);x.setDate(1);x.setMonth(x.getMonth()+(action==='jump-next'?1:-1));jump(null,stamp(x));break;}
      case 'jump-select':if(state.page==='today')scrollToday(date);else goDate(date);break;
      case 'shortcuts':shortcuts(target);break;
      case 'pages':pages();break;
      case 'how-fits':showLegend();break;
      case 'item-calendar':showItemCalendar(id,target);break;
      case 'today-example-future':scrollToday('2026-10-21');break;
      case 'today-example-past':scrollToday('2026-10-07');break;
      case 'today-example-create':showTodayScreen('today-create');break;
      case 'today-example-sync':showTodayScreen('today-sync');break;
      case 'today-example-created':showTodayScreen('today-created');break;
      case 'source-example':showSourceExample();break;
      case 'note':state.note='trip-plan';setPage('note');break;
      case 'open-note':state.note=id;setPage('note');break;
      case 'cards':setPage('cards');break;
      case 'date-link':case 'show-task-day':goDate(id?items.find(i=>i.id===id)?.date||date:date,'day');break;
      case 'select-day':if(state.page==='today')scrollToday(date);else{state.date=date;render();}break;
      case 'note-date':{const note=notes.find(n=>n.id===state.note);addNoteReference(note,state.date);break;}
      case 'calendars':if(phone()||state.page!=='calendar')showDialog('calendars',calendarPanel());else{closeDialog(false);state.panel=!state.panel;render();}$('#screen').value='calendars';break;
      case 'panel-close':if(state.dialog==='calendars')closeDialog();else{state.panel=false;render();}break;
      case 'toggle-calendar':case 'toggle-today':{const c=cal(id);c[action==='toggle-calendar'?'visible':'today']=!c[action==='toggle-calendar'?'visible':'today'];render();if(state.dialog==='calendars')showDialog('calendars',calendarPanel());break;}
      case 'calendar-menu':showDialog('calendar-menu',`${dialogHeader(esc(cal(id).name))}<div class="menu-list">${button('rename-calendar','Rename','page','',`data-id="${id}"`)}${button('rename-calendar','Colour','settings','',`data-id="${id}"`)}${button('delete-calendar','Delete','trash','delete-action',`data-id="${id}"`)}</div>`,target);break;
      case 'rename-calendar':calendarEditor(id,target);break;
      case 'new-calendar':calendarEditor(null,target);break;
      case 'pick-calendar':{const chosen=target.dataset.calendar;if(target.dataset.task){const i=items.find(i=>i.id===target.dataset.task);i.calendar=chosen;render();openTask(i.id);}else{const wrap=target.closest('.calendar-picker-wrap');wrap.querySelector('input').value=chosen;const summary=wrap.querySelector('summary');summary.style.setProperty('--cal',colour(chosen));summary.innerHTML=`<span class="dot"></span><span>${esc(cal(chosen).name)}</span>${icon('down')}`;wrap.querySelector('details').open=false;const hint=$('#composer-calendar-hint');if(hint)hint.hidden=state.page!=='today'||cal(chosen).today;wrap.querySelectorAll('[data-calendar]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.calendar===chosen));}break;}
      case 'choose-color':{const form=$('#calendar-form');form.elements.palette.value=target.dataset.color;form.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',b===target));break;}
      case 'delete-calendar':{if(id==='personal'){toast('Personal is the default calendar. Rename it or change its colour.');break;}const deleted=calendars.find(c=>c.id===id),before=JSON.parse(JSON.stringify(items));calendars=calendars.filter(c=>c.id!==id);for(const i of items)if(i.calendar===id)i.calendar='personal';if(state.lastCalendar===id)state.lastCalendar='personal';closeDialog(false);render();toast(`Deleted '${deleted.name}' · kept its items in Personal`,()=>{calendars.push(deleted);items=before;render();});break;}
      case 'add-time':case 'remove-time':{const i=items.find(x=>x.id===id);i.time=action==='add-time'?'09:00':null;i.duration=i.time?60:null;render();openTask(id);break;}
      case 'agent-task':openTask(items.find(i=>i.assignee==='agent'&&!i.done)?.id);break;
      case 'undo':if(undoAction){undoAction();undoAction=null;$('#toast').classList.remove('show');}break;
    }
  }
  frame.addEventListener('click',e=>{if(e.target.closest('[data-check]'))return;const action=e.target.closest('[data-action]');if(action){handleAction(action.dataset.action,action);return;}const item=e.target.closest('[data-item]');if(item){openTask(item.dataset.item);return;}const cell=e.target.closest('.day-cell');if(cell){state.date=cell.dataset.day;if(phone()){const old=$('#month-scroll').scrollTop;render();$('#month-scroll').scrollTop=old;}else composer(state.date,null,cell);}});
  frame.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-item],[data-day]')){e.preventDefault();e.target.click();}});
  function resizeTitle(t){if(!t)return;t.style.height='auto';t.style.height=t.scrollHeight+'px';}
  frame.addEventListener('input',e=>{const t=e.target;if(!['title','body'].includes(t.dataset.edit))return;const i=items.find(x=>x.id===t.dataset.id);if(t.dataset.edit==='body'||t.value.trim()){i[t.dataset.edit]=t.value;state.sheetDirty=true;}if(t.dataset.edit==='title')resizeTitle(t);});
  frame.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-check]')){const i=items.find(x=>x.id===t.dataset.check);i.done=t.checked;render();if(state.dialog==='task')openTask(i.id);return;}
    if(t.id==='phone-view'){goDate(state.date,t.value);return;}if(t.name==='timed'){$('.time-fields',overlay).hidden=!t.checked;return;}if(t.name==='assignee'&&$('#agent-hint')){$('#agent-hint').hidden=t.value!=='agent';return;}
    if(t.dataset.edit){const i=items.find(x=>x.id===t.dataset.id),key=t.dataset.edit;if(key==='date'&&!validDate(t.value)){t.value=i.date;return;}if(key==='title'&&!t.value.trim()){t.value=i.title;return;}i[key]=key==='duration'?Number(t.value):t.value;ensureRange(i.date);render();if(key==='assignee'||key==='calendar'||key==='time')openTask(i.id);}
  });
  frame.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='composer'){createFromForm();}else if(e.target.id==='jump-form'){if(state.page==='today')scrollToday(e.target.elements.date.value);else goDate(e.target.elements.date.value);}else if(e.target.id==='calendar-form'){const f=new FormData(e.target),name=String(f.get('name')).trim();if(!name)return;const id=e.target.dataset.id;if(id){const c=cal(id);c.name=name;c.palette=String(f.get('palette'));delete c.color;}else{calendars.push({id:'cal-'+(++sequence),name,palette:String(f.get('palette')),visible:true,today:true,database:false});}closeDialog(false);state.panel=true;render();if(phone())showDialog('calendars',calendarPanel());toast(id?'Calendar updated':'Calendar created');}});
  let dragPayload=null;
  frame.addEventListener('dragstart',e=>{const item=e.target.closest('[data-item]'),note=e.target.closest('[data-note]');if(item&&ownedTask(items.find(i=>i.id===item.dataset.item)))dragPayload={type:'task',id:item.dataset.item};else if(note)dragPayload={type:'note',id:note.dataset.note};else{e.preventDefault();return;}e.dataTransfer.setData('text/plain',JSON.stringify(dragPayload));e.dataTransfer.effectAllowed='move';});
  frame.addEventListener('dragover',e=>{const target=e.target.closest('[data-day],[data-slot-day]');if(target&&dragPayload){e.preventDefault();target.classList.add('drop-target');e.dataTransfer.dropEffect='move';}});
  frame.addEventListener('dragleave',e=>{const target=e.target.closest('[data-day],[data-slot-day]');if(target&&!target.contains(e.relatedTarget))target.classList.remove('drop-target');});
  frame.addEventListener('dragend',()=>{dragPayload=null;frame.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));});
  frame.addEventListener('drop',e=>{const target=e.target.closest('[data-day],[data-slot-day]');if(!target||!dragPayload)return;e.preventDefault();const payload=dragPayload;dragPayload=null;const date=target.dataset.day||target.dataset.slotDay;frame.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));if(payload.type==='note')addNoteReference(notes.find(n=>n.id===payload.id),date);else{const i=items.find(x=>x.id===payload.id),before={date:i.date,time:i.time,duration:i.duration};i.date=date;const slot=e.target.closest('[data-time]');if(slot){i.time=slot.dataset.time;i.duration=i.duration||60;}render();toast(`Moved '${i.title}' to ${fmt(date,{day:'numeric',month:'short'})}`,()=>{Object.assign(i,before);render();});}});
  function addNoteReference(note,date){if(!note)return;if(items.some(i=>i.kind==='mention'&&i.noteId===note.id&&i.date===date)){toast(`${shortDate(date)} is already linked to '${note.title}'`);return;}const i={id:'ref-'+(++sequence),title:note.title,date,calendar:note.id==='one-on-one'?'work':'personal',kind:'mention',done:false,assignee:'me',body:note.body,snippet:note.body.split('\n')[0],noteId:note.id};items.push(i);cal(i.calendar).visible=true;render();toast(`Added ${fmt(date,{day:'numeric',month:'short'})} to '${note.title}'`,()=>{items=items.filter(x=>x.id!==i.id);render();});}
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDialog();closeItemSources();return;}if(state.dialog&&e.key==='Tab'){const focusables=[...overlay.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length),first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement=== $('.dialog',overlay))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}
    if(phone()||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,[contenteditable]'))return;const key=e.key.toLowerCase();if(state.dialog&&key!=='?')return;const action={t:'go-today',m:'view-month',w:'view-week',d:'view-day',g:'jump',n:'create','?':'shortcuts',arrowleft:'previous',arrowright:'next',j:'next',k:'previous'}[key];if(action){e.preventDefault();handleAction(action,null);}else if(key==='arrowup'||key==='arrowdown'){e.preventDefault();if(state.page==='today')scrollToday(add(state.date,key==='arrowup'?-1:1));else goDate(add(state.date,key==='arrowup'?-1:1));}
  });
  $('#legend-toggle').addEventListener('click',showLegend);
  $('#theme').addEventListener('change',e=>{document.documentElement.dataset.theme=e.target.value;});
  $('#width').addEventListener('change',e=>{frame.dataset.width=e.target.value;closeDialog(false);render(false);});
  $('#reset').addEventListener('click',()=>{clearTimeout(toastTimer);$('#toast').classList.remove('show');undoAction=null;reset();});
  $('#screen').addEventListener('change',e=>{const screen=e.target.value;clearTimeout(toastTimer);$('#toast').classList.remove('show');undoAction=null;closeDialog(false);if(screen.startsWith('today')){showTodayScreen(screen);return;}if(screen==='source'){showSourceExample();return;}if(screen==='legend'){showLegend();return;}if(['month','week','day'].includes(screen)){goDate(screen==='day'?'2026-10-14':TODAY,screen);return;}if(screen==='cards'||screen==='note'||screen==='today'){state.note='trip-plan';setPage(screen);return;}state.page='calendar';state.date=TODAY;if(screen==='calendars'){state.panel=true;render(false);if(phone())showDialog('calendars',calendarPanel());}else{render(false);if(screen==='task')openTask(items.find(i=>i.kind==='task'&&!i.done&&i.assignee==='agent').id);if(screen==='create')composer();if(screen==='overflow')overflowDay();if(screen==='jump')jump();if(screen==='shortcuts')shortcuts();}$('#screen').value=screen;});
  if(window.innerWidth<600){frame.dataset.width='phone';$('#width').value='phone';}
  reset();
})();
